// 3D viewer of the Cité des Gratte-Ciel and the documents that refer to it, built on iTowns.
// Scene data (window.SCENE) is generated by build_scene.py from the RDF data.
//
// Documents and city objects are linked both ways, at the scale of each reference:
//   - select a place, a building or one of its surfaces (roof, walls) to list the records
//     about it, grouped by scale;
//   - focus a record to highlight what it refers to: a surface, buildings, or a place
//     (its buildings and its outline on the ground).

import * as THREE from 'three';
import * as itowns from 'itowns';

// ── Geometry ────────────────────────────────────────────────────────────────

// Triangulate one planar polygon ring (flat [x, y, z, ...], last point = first).
// Coordinates stay in the scene's frame: EPSG:3946 metres around an origin, z up.
export function triangulateRing(flat) {
  const points = [];
  for (let i = 0; i < flat.length; i += 3) points.push([flat[i], flat[i + 1], flat[i + 2]]);
  if (points.length > 3) {
    const [a, b] = [points[0], points[points.length - 1]];
    if (a[0] === b[0] && a[1] === b[1] && a[2] === b[2]) points.pop();
  }
  if (points.length < 3) return [];

  // Newell normal, then drop its dominant axis to work in 2D
  const n = [0, 0, 0];
  for (let i = 0; i < points.length; i++) {
    const [p, q] = [points[i], points[(i + 1) % points.length]];
    n[0] += (p[1] - q[1]) * (p[2] + q[2]);
    n[1] += (p[2] - q[2]) * (p[0] + q[0]);
    n[2] += (p[0] - q[0]) * (p[1] + q[1]);
  }
  const drop = n.map(Math.abs).indexOf(Math.max(...n.map(Math.abs)));
  const [u, v] = [[1, 2], [2, 0], [0, 1]][drop];
  const contour = points.map((p) => new THREE.Vector2(p[u], p[v]));
  const faces = THREE.ShapeUtils.triangulateShape(contour, []);

  const triangles = [];
  for (const face of faces) for (const index of face) triangles.push(...points[index]);
  return triangles;
}

// One BufferGeometry per surface (all its polygons).
export function surfaceGeometry(surface) {
  const positions = [];
  for (const ring of surface.rings) positions.push(...triangulateRing(ring));
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  return geometry;
}

// ── Documents ───────────────────────────────────────────────────────────────

export const inYear = (reference, year) => year === null || (year >= reference.from && year <= reference.to);

// Records and the buildings they reach, optionally limited to a depicted year.
export function recordsByBuilding(records, year = null) {
  const index = new Map();
  for (const record of records) {
    for (const reference of record.references) {
      if (!inYear(reference, year)) continue;
      for (const building of reference.buildings) {
        if (!index.has(building)) index.set(building, new Set());
        index.get(building).add(record.id);
      }
    }
  }
  return index;
}

// What a set of references highlights, by scale: surfaces, buildings, places.
export function targetsOf(references, places) {
  const targets = { surfaces: new Set(), buildings: new Set(), placeBuildings: new Set(), places: new Set() };
  for (const reference of references) {
    if (reference.scale === 'surface') targets.surfaces.add(reference.target);
    else if (reference.scale === 'building') targets.buildings.add(reference.target);
    else if (reference.place) {
      targets.places.add(reference.place);
      for (const b of places.find((p) => p.id === reference.place)?.buildings ?? reference.buildings) targets.placeBuildings.add(b);
    }
  }
  return targets;
}

// ── Base map (IGN Géoplateforme, EPSG:3946) ────────────────────────────────

const EPSG_3946 = '+proj=lcc +lat_0=46 +lon_0=3 +lat_1=45.25 +lat_2=46.75 +x_0=1700000 +y_0=5200000 '
  + '+ellps=GRS80 +towgs84=0,0,0,0,0,0,0 +units=m +no_defs +type=crs';
const IGN_WMS = 'https://data.geopf.fr/wms-r';
const HALF_SIZE = 450; // metres around the documented buildings
const OUTLINE_HEIGHT = 7; // metres above the scene origin, above the local terrain

// Imagery available for the scene. The historical photographs cover 1950–1965.
export const IMAGERY = {
  historical: { layer: 'ORTHOIMAGERY.ORTHOPHOTOS.1950-1965', format: 'image/png', until: 1965,
    label: 'IGN historical aerial photographs, 1950–1965' },
  current: { layer: 'HR.ORTHOIMAGERY.ORTHOPHOTOS', format: 'image/jpeg',
    label: 'IGN orthophoto, current (20 cm)' },
};

// Which imagery to show for a depicted year in automatic mode.
export function imageryForYear(year) {
  return year !== null && year <= IMAGERY.historical.until ? 'historical' : 'current';
}

function wmsSource(name, format, extent) {
  return new itowns.WMSSource({ url: IGN_WMS, version: '1.3.0', name, style: '', crs: 'EPSG:3946',
    format, extent, transparent: format === 'image/png' });
}

// ── Viewer ──────────────────────────────────────────────────────────────────

const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
const esc = (text) => String(text).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

export function start(scene, elements) {
  const { container, panel, yearInput, yearLabel, allPeriods, summary, imageryMode, imageryLabel } = elements;
  const yearRange = scene.records.flatMap((r) => r.references.flatMap((ref) => [ref.from, ref.to]));
  yearInput.min = Math.min(...yearRange) - 2;
  yearInput.max = new Date().getFullYear();
  yearInput.value = 1936;

  const buildingsById = new Map(scene.buildings.map((b) => [b.id, b]));
  const surfaceToBuilding = new Map(scene.buildings.flatMap((b) => b.surfaces.map((s) => [s.id, b.id])));
  const placesById = new Map(scene.places.map((p) => [p.id, p]));
  const recordsById = new Map(scene.records.map((r) => [r.id, r]));

  // Buildings: one group per building, one mesh per surface (roof, walls)
  const everDocumented = recordsByBuilding(scene.records);
  const surfaceMeshes = [];
  const documentedBox = new THREE.Box3();
  const cityObjects = new THREE.Group();
  for (const building of scene.buildings) {
    const group = new THREE.Group();
    group.userData.building = building.id;
    for (const surface of building.surfaces) {
      const geometry = surfaceGeometry(surface);
      const mesh = new THREE.Mesh(geometry, new THREE.MeshLambertMaterial({ side: THREE.DoubleSide }));
      mesh.userData = { building: building.id, surface: surface.id, role: 'context' };
      mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(geometry, 25), new THREE.LineBasicMaterial({ transparent: true })));
      group.add(mesh);
      surfaceMeshes.push(mesh);
      if (everDocumented.has(building.id)) documentedBox.union(geometry.boundingBox);
    }
    cityObjects.add(group);
  }

  // Place outlines on the ground, shown when a place is selected or targeted
  const outlines = new Map();
  for (const place of scene.places) {
    const points = [];
    for (let i = 0; i < place.outline.length; i += 2) points.push(new THREE.Vector2(place.outline[i], place.outline[i + 1]));
    const fill = new THREE.Mesh(new THREE.ShapeGeometry(new THREE.Shape(points)),
      new THREE.MeshBasicMaterial({ transparent: true, opacity: 0.18, depthTest: false, side: THREE.DoubleSide }));
    const line = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(points.map((p) => new THREE.Vector3(p.x, p.y, 0))),
      new THREE.LineBasicMaterial({ depthTest: false }));
    const outline = new THREE.Group();
    outline.add(fill, line);
    outline.position.z = OUTLINE_HEIGHT;
    outline.renderOrder = 10;
    outline.visible = false;
    outline.userData.place = place.id;
    cityObjects.add(outline);
    outlines.set(place.id, outline);
  }

  const { x: ox, y: oy, z: oz } = scene.origin;
  cityObjects.position.set(ox, oy, oz);
  const centre = documentedBox.getCenter(new THREE.Vector3()).add(cityObjects.position);

  // iTowns planar view in EPSG:3946, seen from the south-east
  itowns.CRS.defs('EPSG:3946', EPSG_3946);
  const extent = new itowns.Extent('EPSG:3946', centre.x - HALF_SIZE, centre.x + HALF_SIZE,
    centre.y - HALF_SIZE, centre.y + HALF_SIZE);
  const view = new itowns.PlanarView(container, extent, {
    placement: { coord: new itowns.Coordinates('EPSG:3946', centre.x, centre.y, oz), heading: -30, tilt: 35, range: 620 },
  });

  const imageryLayers = {};
  for (const [key, imagery] of Object.entries(IMAGERY)) {
    imageryLayers[key] = new itowns.ColorLayer(`ortho-${key}`, { source: wmsSource(imagery.layer, imagery.format, extent) });
    view.addLayer(imageryLayers[key]);
  }
  view.addLayer(new itowns.ElevationLayer('terrain', {
    source: wmsSource('ELEVATION.ELEVATIONGRIDCOVERAGE.HIGHRES', 'image/x-bil;bits=32', extent),
    noDataValue: -99999,
  }));

  view.scene.add(new THREE.HemisphereLight(0xffffff, 0x8899aa, 1.6));
  const sun = new THREE.DirectionalLight(0xffffff, 1.8);
  sun.position.set(centre.x - 300, centre.y - 200, centre.z + 500);
  sun.target.position.copy(centre);
  view.scene.add(sun, sun.target);
  view.scene.add(cityObjects);
  cityObjects.updateMatrixWorld(true);
  sun.target.updateMatrixWorld();

  // ── State ──
  // selection: null | { kind: 'place', id } | { kind: 'building', id, surface }
  let selection = null;
  let focused = null; // record id
  let hovered = null; // building id

  const currentYear = () => (allPeriods.checked ? null : Number(yearInput.value));
  const visibleReferences = (record) => record.references.filter((ref) => inYear(ref, currentYear()));

  function showImagery() {
    const key = imageryMode.value === 'auto' ? imageryForYear(currentYear()) : imageryMode.value;
    for (const [name, layer] of Object.entries(imageryLayers)) layer.visible = name === key;
    imageryLabel.textContent = IMAGERY[key].label;
  }

  // ── 3D highlighting ──
  function roleOf(mesh, index, targets) {
    const { building, surface } = mesh.userData;
    if (targets) {
      if (targets.surfaces.has(surface)) return 'target-surface';
      if (targets.buildings.has(building)) return 'target-building';
      if (targets.placeBuildings.has(building)) return 'target-place';
      return 'context';
    }
    if (selection?.kind === 'place') return placesById.get(selection.id).buildings.includes(building) ? 'place' : 'context';
    if (selection?.kind === 'building' && selection.id === building) {
      return selection.surface === surface ? 'selected-surface' : 'selected';
    }
    return index.get(building)?.size ? 'documented' : 'context';
  }

  function paint() {
    const index = recordsByBuilding(scene.records, currentYear());
    const targets = focused ? targetsOf(visibleReferences(recordsById.get(focused)), scene.places) : null;
    const ramp = [css('--doc-1'), css('--doc-2'), css('--doc-3'), css('--doc-4')];
    const colours = {
      'target-surface': css('--surface'), 'target-building': css('--selected'), 'target-place': css('--place'),
      'selected-surface': css('--surface'), selected: css('--selected'), place: css('--place'), context: css('--context'),
    };
    for (const mesh of surfaceMeshes) {
      const role = roleOf(mesh, index, targets);
      mesh.userData.role = role;
      const count = index.get(mesh.userData.building)?.size ?? 0;
      mesh.material.color.set(role === 'documented' ? ramp[Math.min(count, ramp.length) - 1] : colours[role]);
      if (mesh.userData.building === hovered && role !== 'selected' && role !== 'selected-surface') mesh.material.color.offsetHSL(0, 0, 0.08);
      mesh.children[0].material.color.set(css('--edge'));
      mesh.children[0].material.opacity = role === 'context' ? 0.25 : 0.55;
    }
    const shownPlaces = new Set(targets ? targets.places : selection?.kind === 'place' ? [selection.id] : []);
    for (const [id, outline] of outlines) {
      outline.visible = shownPlaces.has(id);
      for (const part of outline.children) part.material.color.set(css('--place'));
    }
    view.renderer.setClearColor(css('--sky'));
    view.notifyChange();
  }

  // ── Panel ──
  function targetName(reference) {
    if (reference.scale === 'building') return esc(buildingsById.get(reference.target)?.label ?? reference.target);
    if (reference.scale === 'surface') return esc(reference.targetLabel);
    return `${esc(placesById.get(reference.place)?.name ?? reference.targetLabel)} (place)`;
  }

  function referenceRow(reference) {
    const certainty = reference.certainty ? ` <span class="certainty">certainty: ${esc(reference.certainty)}</span>` : '';
    return `<li class="scale-${reference.scale}"><span class="purpose">${esc(reference.purpose)}</span>
      <span>depicts <strong>${esc(reference.depicted)}</strong>${certainty}</span>
      <span>refers to <span class="target">${targetName(reference)}</span></span>
      <span class="muted">asserted ${reference.asserted}</span></li>`;
  }

  function recordCard(record, references) {
    if (!references.length) return '';
    const unique = [...new Map(references.map((ref) => [`${ref.scale}|${ref.target}|${ref.depicted}|${ref.purpose}`, ref])).values()];
    const thumb = [...record.states].reverse().find((s) => s.thumbnail);
    const chain = record.states.map((s) => {
      const label = s.created || 'undated';
      const name = s.uri ? `<a href="${esc(s.uri)}" target="_blank" rel="noopener">${label}</a>` : label;
      return `<span class="state" title="${esc(s.title || s.id)}">${name}</span>`;
    }).join('<span class="arrow">→</span>');
    const source = thumb?.page || record.states.at(-1).uri;
    const isFocused = record.id === focused;
    return `<article class="record${isFocused ? ' focused' : ''}" data-record="${record.id}" tabindex="0" role="button"
        aria-pressed="${isFocused}" title="${isFocused ? 'Click to stop highlighting' : 'Click to highlight what this record refers to'}">
      ${thumb ? `<img src="${esc(thumb.thumbnail)}" alt="" loading="lazy">` : ''}
      <h3><a href="${esc(source)}" target="_blank" rel="noopener">${esc(record.title)}</a></h3>
      <p class="chain"><span class="muted">States</span> ${chain}</p>
      <ul class="refs">${unique.map(referenceRow).join('')}</ul>
      ${thumb?.creator ? `<p class="muted credit">${esc(thumb.creator)}${thumb.licence ? ` · <a href="${esc(thumb.licence)}" target="_blank" rel="noopener">licence</a>` : ''}</p>` : ''}
    </article>`;
  }

  // Records grouped into sections; each section keeps only its own references.
  function sections(groups) {
    let html = '';
    for (const { title, keep } of groups) {
      const cards = scene.records.map((r) => recordCard(r, visibleReferences(r).filter(keep))).join('');
      if (cards) html += `<section><h4>${title}</h4>${cards}</section>`;
    }
    return html || '<p class="empty">No document refers to it for this period.</p>';
  }

  function placeChips() {
    return `<p class="chips">${scene.places.map((p) => `<button type="button" class="chip" data-place="${p.id}">
      ${esc(p.name)} · ${p.buildings.length} buildings</button>`).join('')}</p>`;
  }

  function showPanel() {
    const year = currentYear();
    const when = year === null ? 'all periods' : `depicting ${year}`;
    let html;
    if (selection?.kind === 'place') {
      const place = placesById.get(selection.id);
      html = `<h2>${esc(place.name)}</h2><p class="muted">Place · ${place.buildings.length} buildings · ${when}</p>`
        + sections([
          { title: 'About this place', keep: (ref) => ref.scale === 'place' && ref.place === place.id },
          { title: 'About its buildings and their surfaces', keep: (ref) => ref.scale !== 'place' && ref.buildings.some((b) => place.buildings.includes(b)) },
        ]);
    } else if (selection?.kind === 'building') {
      const building = buildingsById.get(selection.id);
      const surface = building.surfaces.find((s) => s.id === selection.surface);
      const place = scene.places.find((p) => p.buildings.includes(building.id));
      const ownSurfaces = new Set(building.surfaces.map((s) => s.id));
      html = `<h2>${esc(building.label)}</h2><p class="muted">Building${surface ? ` · selected: ${esc(surface.label)}` : ''} · ${when}</p>`
        + sections([
          ...(surface ? [{ title: `About this surface: ${esc(surface.label)}`, keep: (ref) => ref.scale === 'surface' && ref.target === surface.id }] : []),
          { title: 'About this building', keep: (ref) => ref.scale === 'building' && ref.target === building.id },
          { title: surface ? 'About its other surfaces' : 'About its surfaces', keep: (ref) => ref.scale === 'surface' && ownSurfaces.has(ref.target) && ref.target !== surface?.id },
          { title: place ? `About its place: ${esc(place.name)}` : 'About its place', keep: (ref) => ref.scale === 'place' && ref.buildings.includes(building.id) },
        ]);
    } else {
      html = `<h2>${esc(scene.place.name)}</h2><p class="muted">${when}. Click a building, a roof or a wall, or a place below; click a record to highlight what it refers to.</p>`
        + placeChips()
        + sections([{ title: 'All records', keep: () => true }]);
    }
    panel.innerHTML = html;
    panel.querySelector('.record.focused')?.scrollIntoView({ block: 'start' });
    yearLabel.textContent = year === null ? '' : year;
    summary.textContent = `${scene.buildings.length} buildings · ${scene.records.length} records · ${everDocumented.size} documented buildings`;
  }

  // ── Shareable view: #place= | #building=&surface= , &record=, &year=, &imagery= ──
  function readHash() {
    const params = new URLSearchParams(location.hash.slice(1));
    if (placesById.has(params.get('place'))) selection = { kind: 'place', id: params.get('place') };
    else if (buildingsById.has(params.get('building'))) {
      const surface = surfaceToBuilding.get(params.get('surface')) === params.get('building') ? params.get('surface') : null;
      selection = { kind: 'building', id: params.get('building'), surface };
    } else selection = null;
    focused = recordsById.has(params.get('record')) ? params.get('record') : null;
    const year = Number(params.get('year'));
    allPeriods.checked = !params.has('year') || Number.isNaN(year);
    if (!allPeriods.checked) yearInput.value = year;
    imageryMode.value = ['current', 'historical'].includes(params.get('imagery')) ? params.get('imagery') : 'auto';
  }

  function writeHash() {
    const params = new URLSearchParams();
    if (selection?.kind === 'place') params.set('place', selection.id);
    if (selection?.kind === 'building') {
      params.set('building', selection.id);
      if (selection.surface) params.set('surface', selection.surface);
    }
    if (focused) params.set('record', focused);
    if (!allPeriods.checked) params.set('year', yearInput.value);
    if (imageryMode.value !== 'auto') params.set('imagery', imageryMode.value);
    history.replaceState(null, '', params.toString() ? `#${params}` : location.pathname);
  }

  function refresh() {
    showImagery();
    paint();
    showPanel();
    writeHash();
  }

  // ── Interaction ──
  // Picking on the surfaces (coordinates from the container's rectangle: iTowns overlays
  // label elements on its canvas, so the event target and its offsets are not the canvas's)
  const raycaster = new THREE.Raycaster();
  const pointer = new THREE.Vector2();
  function pick(event) {
    const rect = container.getBoundingClientRect();
    pointer.set(((event.clientX - rect.left) / rect.width) * 2 - 1, -((event.clientY - rect.top) / rect.height) * 2 + 1);
    raycaster.setFromCamera(pointer, view.camera3D);
    return raycaster.intersectObjects(surfaceMeshes, false)[0]?.object.userData ?? null;
  }
  let downAt = null;
  container.addEventListener('pointerdown', (e) => { downAt = [e.clientX, e.clientY]; });
  container.addEventListener('pointerup', (e) => {
    if (!downAt || Math.hypot(e.clientX - downAt[0], e.clientY - downAt[1]) > 4) return;
    const hit = pick(e);
    selection = hit ? { kind: 'building', id: hit.building, surface: hit.surface } : null;
    focused = null;
    refresh();
  });
  container.addEventListener('pointermove', (e) => {
    if (e.buttons) return;
    const id = pick(e)?.building ?? null;
    if (id !== hovered) {
      hovered = id;
      container.style.cursor = id ? 'pointer' : '';
      paint();
    }
  });

  // Panel: focus a record (highlight its targets), select a place
  function onPanelActivate(event) {
    if (event.target.closest('a')) return;
    const chip = event.target.closest('[data-place]');
    if (chip) {
      selection = { kind: 'place', id: chip.dataset.place };
      focused = null;
      refresh();
      return;
    }
    const card = event.target.closest('[data-record]');
    if (card) {
      focused = focused === card.dataset.record ? null : card.dataset.record;
      paint();
      showPanel();
      writeHash();
    }
  }
  panel.addEventListener('click', onPanelActivate);
  panel.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onPanelActivate(e); } });

  yearInput.addEventListener('input', () => { allPeriods.checked = false; refresh(); });
  allPeriods.addEventListener('change', refresh);
  imageryMode.addEventListener('change', refresh);
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change', paint);
  window.addEventListener('hashchange', () => { readHash(); showImagery(); paint(); showPanel(); });

  readHash();
  refresh();
  return view;
}
